function sr(g: number) : string {
    let w : string = ""
    let m : boolean = true
    for (let i : number = 0; i <= (g/16); i++) {
        if (m) {
            w = w + "SUKI"
        } else {
            w = w + "NANDA!"
        }
        m = !m
    }
    return w
}

function quad(n : boolean) : boolean {
    for (let i : number = 0; i <= n; i++) {
        console.log(n ** 2)
        return
    }
}

function a(x : number, cx : number) : string {
    if (x == cx) return ""

    return a(x, cx+1) + cx
}

function b(y : number, cy : number) : string {
    if (y == cy) return ""

    return b(y, cy+1) + "\n" + a(10, 1)
}
